הנה משחק Snake מודרני, רספונסיבי ועם עיצוב עדכני. 

```html
<!-- file: snake.html -->
<!DOCTYPE html>
<html lang="he" dir="ltr">
<head>
<meta charset="UTF-8">
<title>Snake – משחק נחש מודרני</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
:root {
 --bg-light: #f0f4f8;
 --bg-dark: #1e1e2f;
 --primary: #4a90e2;
 --accent: #ff6b6b;
 --text: #212121;
 --radius: 12px;
 --shadow: 0 4px 12px rgba(0,0,0,0.1);
 --transition: 0.2s ease;
}
@media (prefers-color-scheme: dark) {
 :root {
 --bg-light: var(--bg-dark);
 --text: #e0e0e0;
 }
}
body {
 margin:0;
 font-family: system-ui, -apple-system, sans-serif;
 background: var(--bg-light);
 color: var(--text);
 display:flex;
 flex-direction: column;
 align-items:center;
 justify-content:flex-start;
 min-height:100vh;
 padding: 1rem;
}
h1 {
 margin:0.5rem 0 0.2rem;
 font-size: 1.8rem;
 color: var(--primary);
}
#score {
 font-size: 1.2rem;
 margin-bottom: 0.5rem;
}
canvas {
 background: #fff;
 border-radius: var(--radius);
 box-shadow: var(--shadow);
 touch-action: none;
}
button {
 margin-top: 1rem;
 padding: 0.6rem 1.2rem;
 font-size: 1rem;
 background: var(--primary);
 color:#fff;
 border:none;
 border-radius: var(--radius);
 cursor:pointer;
 transition: var(--transition);
}
button:hover { background: var(--accent); }
button:focus { outline:2px solid var(--accent); }
@media (max-width: 768px) {
 canvas { width: 90vw; height: 90vw; }
}
</style>
</head>
<body>
<h1>🐍 Snake</h1>
<div id="score">ניקוד: 0</div>
<canvas id="gameCanvas" width="400" height="400" aria-label="משחק נחש"></canvas>
<button id="restartBtn" hidden>התחל מחדש</button>

<script>
(() => {
 const canvas = document.getElementById('gameCanvas');
 const ctx = canvas.getContext('2d');
 const scoreEl = document.getElementById('score');
 const restartBtn = document.getElementById('restartBtn');

 const config = {
 rows: 20,
 cols: 20,
 cellSize: canvas.width / 20,
 speed: 120, // ms between moves
 };

 let snake, food, direction, nextDirection, gameLoop, score, isGameOver;

 const init = () => {
 snake = [{x:9, y:9}];
 direction = {x:0, y:-1};
 nextDirection = direction;
 placeFood();
 score = 0;
 isGameOver = false;
 scoreEl.textContent = `ניקוד: ${score}`;
 restartBtn.hidden = true;
 clearInterval(gameLoop);
 gameLoop = setInterval(update, config.speed);
 };

 const placeFood = () => {
 let valid = false;
 while (!valid) {
 food = {
 x: Math.floor(Math.random()*config.cols),
 y: Math.floor(Math.random()*config.rows)
 };
 valid = !snake.some(seg=> seg.x===food.x && seg.y===food.y);
 }
 };

 const draw = () => {
 ctx.clearRect(0,0,canvas.width,canvas.height);
 // draw food
 ctx.fillStyle = varGet('--accent');
 ctx.fillRect(food.x*config.cellSize, food.y*config.cellSize, config.cellSize, config.cellSize);
 // draw snake
 ctx.fillStyle = varGet('--primary');
 snake.forEach((seg,i)=> {
 ctx.fillRect(seg.x*config.cellSize, seg.y*config.cellSize, config.cellSize, config.cellSize);
 });
 };

 const varGet = (name)=> getComputedStyle(document.documentElement).getPropertyValue(name).trim();

 const update = () => {
 direction = nextDirection;
 const head = {x: snake[0].x + direction.x, y: snake[0].y + direction.y};

 // wall collision (wrap)
 head.x = (head.x + config.cols) % config.cols;
 head.y = (head.y + config.rows) % config.rows;

 // self collision
 if (snake.some(seg=> seg.x===head.x && seg.y===head.y)) {
 gameOver();
 return;
 }

 snake.unshift(head);
 if (head.x===food.x && head.y===food.y) {
 score++;
 scoreEl.textContent = `ניקוד: ${score}`;
 placeFood();
 } else {
 snake.pop();
 }
 draw();
 };

 const gameOver = () => {
 clearInterval(gameLoop);
 isGameOver = true;
 restartBtn.hidden = false;
 ctx.fillStyle = 'rgba(0,0,0,0.5)';
 ctx.fillRect(0,0,canvas.width,canvas.height);
 ctx.fillStyle = '#fff';
 ctx.font = 'bold 24px sans-serif';
 ctx.textAlign = 'center';
 ctx.fillText('המשחק נגמר', canvas.width/2, canvas.height/2);
 };

 const changeDirection = (dx,dy) => {
 // prevent reverse
 if (dx===-direction.x && dy===-direction.y) return;
 nextDirection = {x:dx, y:dy};
 };

 // Keyboard controls
 document.addEventListener('keydown', e=>{
 if (isGameOver) return;
 switch(e.key) {
 case 'ArrowUp': case 'w': changeDirection(0,-1); break;
 case 'ArrowDown': case 's': changeDirection(0,1); break;
 case 'ArrowLeft': case 'a': changeDirection(-1,0); break;
 case 'ArrowRight': case 'd': changeDirection(1,0); break;
 }
 });

 // Touch swipe controls
 let touchStart = null;
 canvas.addEventListener('touchstart', e=> {
 const t = e.touches[0];
 touchStart = {x:t.clientX, y:t.clientY};
 });
 canvas.addEventListener('touchend', e=> {
 if (!touchStart) return;
 const t = e.changedTouches[0];
 const dx = t.clientX - touchStart.x;
 const dy = t.clientY - touchStart.y;
 if (Math.abs(dx) > Math.abs(dy)) {
 if (dx > 0) changeDirection(1,0);
 else changeDirection(-1,0);
 } else {
 if (dy > 0) changeDirection(0,1);
 else changeDirection(0,-1);
 }
 touchStart = null;
 });

 restartBtn.addEventListener('click', init);

 // start
 init();
})();
</script>
</body>
</html>
```

- משחק נחש קלאסי עם שליטה במקלדת ובמגע, כולל עטיפה של הקירות. 
- ניקוד מתעדכן בזמן אמת, והמשחק מציג מסך "Game Over" עם אפשרות להתחלה מחדש. 
- ניתן להרחיב בקלות: להוסיף רמות קושי, אפקטים קוליים, או מצבי משחק שונים (למשל, קירות קבועים).

הנה גרסה משודרגת עם עיצוב מלוטש, מעוגל, צבעוני ומלא חיים – עם ראש נחש שכולל עיניים, אוכל מעוגל עם ניצוץ, ואפקטים ויזואליים יפים.

