 font-size: 0.85rem;
 color: var(--text-sub);
 text-align: center;
}
</style>
</head>
<body>

<div class="game-container">
 <div class="header">
 <div class="title-group">
 <h1>Snake</h1>
 </div>
 <div class="score-badge">
 <div>ניקוד: <span id="scoreVal">0</span></div>
 <div>שיא: <span id="highVal">0</span></div>
 </div>
 </div>

 <div class="canvas-wrapper">
 <canvas id="gameCanvas" width="400" height="400"></canvas>

 <div id="overlay" class="overlay">
 <h2 id="overlayTitle">משחק חדש</h2>
 <button id="startBtn" class="btn">התחל משחק</button>
 </div>
 </div>

 <div class="controls-hint">
 השתמש במקשי החצים / WASD או בהחלקה (Swipe) בסמארטפון
 </div>
</div>

<script>
(() => {
 const canvas = document.getElementById('gameCanvas');
 const ctx = canvas.getContext('2d');
 const scoreVal = document.getElementById('scoreVal');
 const highVal = document.getElementById('highVal');
 const overlay = document.getElementById('overlay');
 const overlayTitle = document.getElementById('overlayTitle');
 const startBtn = document.getElementById('startBtn');

 const GRID_SIZE = 20;
 const CELL_SIZE = canvas.width / GRID_SIZE;

 let snake = [];
 let food = {};
 let dir = { x: 1, y: 0 };
 let nextDir = { x: 1, y: 0 };
 let gameInterval = null;
 let score = 0;
 let highScore = localStorage.getItem('snake_high_score') || 0;
 let isPlaying = false;

 highVal.textContent = highScore;

 function initGame() {
 snake = [
 { x: 5, y: 10 },
 { x: 4, y: 10 },
 { x: 3, y: 10 }
 ];
 dir = { x: 1, y: 0 };
 nextDir = { x: 1, y: 0 };
 score = 0;
 scoreVal.textContent = score;
 spawnFood();
 isPlaying = true;
 overlay.classList.add('hidden');

 if (gameInterval) clearInterval(gameInterval);
 gameInterval = setInterval(gameStep, 100);
 }

 function spawnFood() {
 let valid = false;
 while (!valid) {
 food = {
 x: Math.floor(Math.random() * GRID_SIZE),
 y: Math.floor(Math.random() * GRID_SIZE)
 };
 valid = !snake.some(seg => seg.x === food.x && seg.y === food.y);
 }
 }

 function gameStep() {
 dir = nextDir;
 const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

 // Collision with walls
 if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
 endGame();
 return;
 }

 // Collision with self
 if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
 endGame();
 return;
 }

 snake.unshift(head);

 // Eat food
 if (head.x === food.x && head.y === food.y) {
 score += 10;
 scoreVal.textContent = score;
 if (score > highScore) {
 highScore = score;
 highVal.textContent = highScore;
 localStorage.setItem('snake_high_score', highScore);
 }
 spawnFood();
 } else {
 snake.pop();
 }

 draw();
 }

 function draw() {
 // Clear background
 ctx.fillStyle = '#090d16';
 ctx.fillRect(0, 0, canvas.width, canvas.height);

 // Draw subtle grid lines
 ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
 ctx.lineWidth = 1;
 for (let i = 0; i <= canvas.width; i += CELL_SIZE) {
 ctx.beginPath();
 ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height);
 ctx.stroke();
 ctx.beginPath();
 ctx.moveTo(0, i); ctx.lineTo(canvas.width, i);
 ctx.stroke();
 }

 // Draw Food (Shining Red Orb)
 const foodX = food.x * CELL_SIZE + CELL_SIZE / 2;
 const foodY = food.y * CELL_SIZE + CELL_SIZE / 2;
 const foodRadius = (CELL_SIZE / 2) - 2;

 ctx.save();
 ctx.shadowColor = '#f43f5e';
 ctx.shadowBlur = 12;
 ctx.fillStyle = '#f43f5e';

 ctx.beginPath();
 ctx.arc(foodX, foodY, foodRadius, 0, Math.PI * 2);
 ctx.fill();
 ctx.restore();

 // Draw Snake
 snake.forEach((segment, index) => {
 const segX = segment.x * CELL_SIZE;
 const segY = segment.y * CELL_SIZE;

 // Head gets a brighter color
 if (index === 0) {
 ctx.fillStyle = '#34d399';
 ctx.shadowColor = '#34d399';
 ctx.shadowBlur = 8;
 } else {
 ctx.fillStyle = '#22c55e';
 ctx.shadowColor = '#22c55e';
 ctx.shadowBlur = 4;
 }

 ctx.fillRect(segX + 1, segY + 1, CELL_SIZE - 2, CELL_SIZE - 2);
 ctx.shadowBlur = 0; // reset blur for next segment
 });
 }

 function endGame() {
 clearInterval(gameInterval);
 isPlaying = false;
 overlayTitle.textContent = 'המשחק נגמר';
 startBtn.textContent = 'שחק שוב';
 overlay.classList.remove('hidden');
 }

 // Keyboard controls
 window.addEventListener('keydown', e => {
 if (!isPlaying) return;
 switch (e.key) {
 case 'ArrowUp':
 case 'w':
 case 'W':
 if (dir.y !== 1) nextDir = { x: 0, y: -1 };
 break;
 case 'ArrowDown':
 case 's':
 case 'S':
 if (dir.y !== -1) nextDir = { x: 0, y: 1 };
 break;
 case 'ArrowLeft':
 case 'a':
 case 'A':
 if (dir.x !== 1) nextDir = { x: -1, y: 0 };
 break;
 case 'ArrowRight':
 case 'd':
 case 'D':
 if (dir.x !== -1) nextDir = { x: 1, y: 0 };
 break;
 }
 });

 // Touch controls (swipe)
 let touchStartX = null;
 let touchStartY = null;

 canvas.addEventListener('touchstart', e => {
 const touch = e.touches[0];
 touchStartX = touch.clientX;
 touchStartY = touch.clientY;
 });

 canvas.addEventListener('touchend', e => {
 if (!touchStartX || !touchStartY) return;
 const touch = e.changedTouches[0];
 const dx = touch.clientX - touchStartX;
 const dy = touch.clientY - touchStartY;

 if (Math.abs(dx) > Math.abs(dy)) {
 // Horizontal swipe
 if (dx > 0 && dir.x !== -1) nextDir = { x: 1, y: 0 };
 else if (dx < 0 && dir.x !== 1) nextDir = { x: -1, y: 0 };
 } else {
 // Vertical swipe
 if (dy > 0 && dir.y !== -1) nextDir = { x: 0, y: 1 };
 else if (dy < 0 && dir.y !== 1) nextDir = { x: 0, y: -1 };
 }

 touchStartX = null;
 touchStartY = null;
 });

 // Start button handler
 startBtn.addEventListener('click', () => {
 initGame();
 });

 // Initial draw (show empty board)
 draw();
})();
```

תיקנתי את הבעיה בלחצנים והוספתי מקשי ניווט מגע (לחצני חיצים) על המסך עצמו, כדי שתוכל לשחק בקלות גם דרך הנייד או דרך העכבר במחשב.

