 scoreVal.textContent = score;
 spawnFood();
 isPlaying = true;
 overlay.classList.add('hidden');

 if (gameInterval) clearInterval(gameInterval);
 gameInterval = setInterval(gameStep, 110);
 draw();
 }

 function spawnFood() {
