<div class="game-card">
 <div class="header">
 <div class="title-badge">
 <h1>Snake Ultra</h1>
 </div>
 <div class="scores-container">
 <div class="score-box">
 <div class="score-label">ניקוד</div>
 <div class="score-value" id="scoreVal">0</div>
 </div>
 <div class="score-box">
 <div class="score-label">שיא</div>
 <div class="score-value" id="highVal">0</div>
 </div>
 </div>
 </div>

 <div class="canvas-container">
 <canvas id="gameCanvas"></canvas>
 <div id="overlay" class="overlay">
 <h2 id="overlayTitle" class="overlay-title">משחק נחש</h2>
 <div id="overlaySub" class="overlay-sub">השתמש בחיצים או במקשי המגע</div>
 <button id="startBtn" class="btn-primary" type="button">התחל משחק</button>
 </div>
 </div>

 <div class="controls-grid">
 <button class="ctrl-btn btn-up" id="ctrlUp" type="button">▲</button>
 <button class="ctrl-btn btn-left" id="ctrlLeft" type="button">◄</button>
 <button class="ctrl-btn btn-down" id="ctrlDown" type="button">▼</button>
 <button class="ctrl-btn btn-right" id="ctrlRight" type="button">►</button>
 </div>
</div>

<script>
document.addEventListener('DOMContentLoaded', () => {
 const canvas = document.getElementById('gameCanvas');
 const ctx = canvas.getContext('2d');
 const scoreVal = document.getElementById('scoreVal');
 const highVal = document.getElementById('highVal');
 const overlay = document.getElementById('overlay');
 const overlayTitle = document.getElementById('overlayTitle');
 const overlaySub = document.getElementById('overlaySub');
 const startBtn = document.getElementById('startBtn');

 const GRID_SIZE = 20;
 let cellSize = 20;

 let snake = [];
 let food = {};
 let dir = { x: 1, y: 0 };
 let nextDir = { x: 1, y: 0 };
 let gameInterval = null;
 let score = 0;
 let highScore = parseInt(localStorage.getItem('snake_high_score') || '0', 10);
 let isPlaying = false;

 highVal.textContent = highScore;

 function resizeCanvas() {
 const container = canvas.parentElement;
 const size = Math.floor(container.clientWidth);
 canvas.width = size;
 canvas.height = size;
 cellSize = size / GRID_SIZE;
 draw();
 }

 function initGame() {
 snake = [{ x: 5, y: 10 }, { x: 4, y: 10 }, { x: 3, y: 10 }];
 dir = { x: 1, y: 0 };
 nextDir = { x: 1, y: 0 };
 score = 0;
 scoreVal.textContent = score;
 spawnFood();
 isPlaying = true;
 overlay.classList.add('hidden');

 if (gameInterval) clearInterval(gameInterval);
 gameInterval = setInterval(gameStep, 100);
 draw();
 }

 function spawnFood() {
 let valid = false;
 while (!valid) {
 food = {
 x: Math.floor(Math.random() * GRID_SIZE),
 y: Math.floor(Math.random() * GRID_SIZE)
 };
 valid = !snake.some(seg => seg.x === food.x && seg.y === food.y);
 }
 }

 function gameStep() {
 dir = nextDir;
 const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

 // קירות
 if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
 endGame(); return;
 }
 // גוף
 if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
 endGame(); return;
 }

 snake.unshift(head);

 // אוכל
 if (head.x === food.x && head.y === food.y) {
 score += 10;
 scoreVal.textContent = score;
 if (score > highScore) {
 highScore = score;
 highVal.textContent = highScore;
 localStorage.setItem('snake_high_score', highScore);
 }
 spawnFood();
 } else {
 snake.pop();
 }

 draw();
 }

 function draw() {
 ctx.fillStyle = '#070b14';
 ctx.fillRect(0, 0, canvas.width, canvas.height);

 // רשת
 ctx.strokeStyle = 'rgba(255, 255, 255, 0.02)';
 ctx.lineWidth = 1;
 for (let i = 0; i <= canvas.width; i += cellSize) {
 ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, canvas.height); ctx.stroke();
 ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(canvas.width, i); ctx.stroke();
 }

 if (!isPlaying && snake.length === 0) return;

 // אוכל
 const foodX = food.x * cellSize + cellSize / 2;
 const foodY = food.y * cellSize + cellSize / 2;
 ctx.save();
 ctx.shadowColor = '#f43f5e';
 ctx.shadowBlur = 12;
 ctx.fillStyle = '#f43f5e';
 ctx.beginPath();
 ctx.arc(foodX, foodY, (cellSize / 2) - 2, 0, Math.PI * 2);
 ctx.fill();
 ctx.restore();

 // נחש
 snake.forEach((seg, idx) => {
 const segX = seg.x * cellSize;
 const segY = seg.y * cellSize;
 ctx.save();
 if (idx === 0) {
 ctx.shadowColor = '#34d399';
 ctx.shadowBlur = 8;
 ctx.fillStyle = '#34d399';
 } else {
 ctx.fillStyle = '#10b981';
 }
 ctx.beginPath();
 ctx.roundRect(segX + 1, segY + 1, cellSize - 2, cellSize - 2, idx === 0 ? 6 : 4);
 ctx.fill();
 ctx.restore();
 });
 }

 function endGame() {
 clearInterval(gameInterval);
 isPlaying = false;
 overlayTitle.textContent = 'המשחק נגמר!';
 overlaySub.textContent = `הגעת ל-${score} נקודות`;
 startBtn.textContent = 'שחק שוב';
 overlay.classList.remove('hidden');
 }

 window.addEventListener('keydown', e => {
 if (!isPlaying) return;
 switch (e.key) {
 case 'ArrowUp': case 'w': case 'W':
 if (dir.y !== 1) nextDir = { x: 0, y: -1 }; break;
 case 'ArrowDown': case 's': case 'S':
 if (dir.y !== -1) nextDir = { x: 0, y: 1 }; break;
 case 'ArrowLeft': case 'a': case 'A':
 if (dir.x !== 1) nextDir = { x: -1, y: 0 }; break;
 case 'ArrowRight': case 'd': case 'D':
 if (dir.x !== -1) nextDir = { x: 1, y: 0 }; break;
 }
 });

 function setDirection(x, y) {
 if (!isPlaying) return;
 if (x !== 0 && dir.x !== -x) nextDir = { x, y: 0 };
 if (y !== 0 && dir.y !== -y) nextDir = { x: 0, y };
 }

 document.getElementById('ctrlUp').addEventListener('click', () => setDirection(0, -1));
 document.getElementById('ctrlDown').addEventListener('click', () => setDirection(0, 1));
 document.getElementById('ctrlLeft').addEventListener('click', () => setDirection(-1, 0));
 document.getElementById('ctrlRight').addEventListener('click', () => setDirection(1, 0));

 startBtn.addEventListener('click', () => initGame());

 window.addEventListener('resize', resizeCanvas);
 resizeCanvas();
});
</script>
</body>
</html>

תיקנתי את זה! הנה המשחק המעודכן – כל המקשים (למעלה, למטה, ימינה, שמאלה) מופיעים עכשיו בבירור ובגודל נוח למגע ולמקלדת.

