 let snake, food, direction, nextDirection, score, gameLoop, isGameOver;

 const init = () => {
 snake = [{x: 9, y: 9}];
 direction = {x: 1, y: 0};
 nextDirection = direction;
 placeFood();
 score = 0;
 isGameOver = false;
 scoreEl.textContent = 'נקודות: 0';
 overlay.classList.remove('show');
 restartBtn.style.display = 'none';
 clearInterval(gameLoop);
 gameLoop = setInterval(update, config.speed);
 canvas.focus();
 };

 const placeFood = () => {
 let valid = false;
 while (!valid) {
 food = {
 x: Math.floor(Math.random() * config.cols),
 y: Math.floor(Math.random() * config.rows)
 };
 valid = !snake.some(seg => seg.x === food.x && seg.y === food.y);
 }
 };

 const drawCell = (x, y, color) => {
 ctx.fillStyle = color;
 ctx.fillRect(x * config.cellSize, y * config.cellSize, config.cellSize, config.cellSize);
 };

 const render = () => {
 ctx.clearRect(0,0,canvas.width,canvas.height);
 // grid
 ctx.strokeStyle = '#3a3a55';
 for(let i=0;i<=config.cols;i++){
 ctx.beginPath();
 ctx.moveTo(i*config.cellSize,0);
 ctx.lineTo(i*config.cellSize,canvas.height);
 ctx.stroke();
 }
 for(let i=0;i<=config.rows;i++){
 ctx.beginPath();
 ctx.moveTo(0,i*config.cellSize);
 ctx.lineTo(canvas.width,i*config.cellSize);
 ctx.stroke();
 }
 // snake
 snake.forEach((seg, idx) => {
 drawCell(seg.x, seg.y, idx===0? 'var(--snake-head)' : 'var(--snake-body)');
 });
 // food
 drawCell(food.x, food.y, 'var(--food)');
 };

 const update = () => {
 // apply queued direction if not opposite
 if (!((nextDirection.x === -direction.x && nextDirection.y === 0) ||
 (nextDirection.y === -direction.y && nextDirection.x === 0))) {
 direction = nextDirection;
 }

 const newHead = {
 x: (snake[0].x + direction.x + config.cols) % config.cols,
 y: (snake[0].y + direction.y + config.rows) % config.rows
 };

 // collision with self
 if (snake.some(seg => seg.x === newHead.x && seg.y === newHead.y)) {
 endGame();
 return;
 }

 snake.unshift(newHead);

 // eat food
 if (newHead.x === food.x && newHead.y === food.y) {
 score++;
 scoreEl.textContent = `נקודות: ${score}`;
 placeFood();
 } else {
 snake.pop();
 }

 render();
 };

 const endGame = () => {
 clearInterval(gameLoop);
 isGameOver = true;
 overlay.textContent = `המשחק נגמר! ניקוד: ${score}`;
 overlay.classList.add('show');
 restartBtn.style.display = 'inline-block';
 };

 // controls
 const keyMap = {
 ArrowUp: {x:0, y:-1},
 ArrowDown: {x:0, y:1},
 ArrowLeft: {x:-1, y:0},
 ArrowRight: {x:1, y:0},
 w: {x:0, y:-1},
 s: {x:0, y:1},
 a: {x:-1, y:0},
 d: {x:1, y:0}
 };

 document.addEventListener('keydown', e => {
 if (keyMap[e.key] && !isGameOver) {
 nextDirection = keyMap[e.key];
 }
 });

 restartBtn.addEventListener('click', init);
 canvas.addEventListener('click', () => canvas.focus());

 // start
 init();
})();
</script>
</body>
</html>
```

- משחק Snake קלאסי עם שליטה במקשי החצים (או WASD) ועם רמת קושי קבועה. 
- מציג ניקוד בזמן אמת, מסך סיום, וכפתור להתחלה מחדש. 
- ניתן להרחיב על‑ידי שינוי מהירות, הוספת רמות קושי, או הוספת אפקטים קוליים.

הנה גרסה של משחק Snake שבה השליטה מתבצעת באמצעות כפתורים על‑מסך במקום מקשי המקלדת. כל הקוד נמצא בקובץ HTML יחיד, כך שהמשחק רץ מיד בדפדפן.

